const OWNER={PLAYER:'player',ENEMY:'enemy'};
const TERRAIN={grassland:{icon:'🌿',label:'Grassland'},mountain:{icon:'⛰️',label:'Mountain'},water:{icon:'🌊',label:'Water'},desert:{icon:'🏜️',label:'Desert'}};
const BUILDINGS={farm:{icon:'🌾',label:'Farm',cost:50,production:20,maintenance:1,durability:90,sensitivity:.7},factory:{icon:'🏭',label:'Factory',cost:100,production:40,maintenance:3,durability:110,sensitivity:1.2},wind:{icon:'🌬️',label:'Wind',cost:60,production:10,maintenance:1,durability:80,sensitivity:1},solar:{icon:'☀️',label:'Solar',cost:80,production:25,maintenance:1,durability:75,sensitivity:.6},mine:{icon:'⛏️',label:'Mine',cost:90,production:30,maintenance:2,durability:120,sensitivity:.8},lab:{icon:'🧪',label:'Lab',cost:75,production:15,maintenance:2,durability:85,sensitivity:.5}};
const MOD={grassland:{farm:1.2,factory:1,wind:1,solar:.9,mine:.8,lab:1},mountain:{farm:.7,factory:.9,wind:1.3,solar:1,mine:1.5,lab:1.1},water:{farm:1.1,factory:.7,wind:1.4,solar:1.2,mine:.5,lab:.9},desert:{farm:.6,factory:1,wind:1.1,solar:1.8,mine:1,lab:.8}};
const POWERS=[{id:'sunny',icon:'☀️',name:'Sunny Boost',cost:30,mult:1.5,duration:3,benefit:true},{id:'rain',icon:'🌧️',name:'Rainfall',cost:35,mult:1.25,duration:2,benefit:true},{id:'storm',icon:'⛈️',name:'Storm',cost:40,mult:.55,duration:2,damage:12},{id:'fog',icon:'🌫️',name:'Fog',cost:25,mult:.85,duration:2,damage:3},{id:'hail',icon:'🧊',name:'Hailstorm',cost:45,mult:.65,duration:2,damage:16},{id:'heatwave',icon:'🌡️',name:'Heatwave',cost:55,mult:.7,duration:3,damage:10},{id:'blizzard',icon:'❄️',name:'Blizzard',cost:55,mult:.5,duration:2,damage:14},{id:'lightning',icon:'⚡',name:'Lightning',cost:45,mult:.6,duration:1,damage:22}];
const COMMANDERS=[
  {name:'Ava Storm',city:'New York',station:'Metro 8',role:'Chief Meteorologist',portrait:10,icon:'BOLT',power:'Eye of the Storm',desc:'Double all of your production this turn.',kind:'boost'},
  {name:'Liam Frost',city:'Moscow',station:'Northline News',role:'Winter Weather Specialist',portrait:3,icon:'✣',power:'Deep Freeze',desc:'Suppress every rival building for one turn.',kind:'freeze'},
  {name:'Sophia Ray',city:'Los Angeles',station:'Pacific 7',role:'Morning Meteorologist',portrait:4,icon:'☀',power:'Solar Flare',desc:'Gain 60 credits immediately.',kind:'money'},
  {name:'Ethan Thunder',city:'Tokyo',station:'Weather One',role:'Severe Weather Anchor',portrait:1,icon:'ϟ',power:'Chain Lightning',desc:'Deal 18 damage to every rival building.',kind:'damage'},
  {name:'Isabella Rain',city:'London',station:'Climate Desk 4',role:'Agricultural Forecaster',portrait:8,icon:'≋',power:'Growing Season',desc:'Farms produce triple this turn.',kind:'farm'},
  {name:'Noah Gale',city:'Chicago',station:'Great Lakes 5',role:'Storm Chaser',portrait:5,icon:'↻',power:'Pressure Drop',desc:'Remove one random rival building.',kind:'remove'},
  {name:'Mia Heatwave',city:'Sydney',station:'Southern Cross',role:'Climate Correspondent',portrait:2,icon:'↑',power:'Heat Dome',desc:'Solar arrays produce triple this turn.',kind:'solar'},
  {name:'Oliver Fog',city:'San Francisco',station:'Bay Weather 4',role:'Coastal Meteorologist',portrait:7,icon:'░',power:'Hidden Front',desc:'Block the rival weather action this turn.',kind:'block'},
  {name:'Charlotte Calm',city:'Paris',station:'Forecast Network',role:'Evening Weather Anchor',portrait:6,icon:'○',power:'Clear Skies',desc:'Remove all harmful effects from your tiles.',kind:'clear'},
  {name:'James Eclipse',city:'Cairo',station:'Night Sky News',role:'Night Meteorologist',portrait:9,icon:'◐',power:'Total Eclipse',desc:'Halve rival production this turn.',kind:'eclipse'}
];
const SAVE='weather-wars-save-v3';const TUTORIAL='weather-wars-tutorial-seen';let state,selectedAction=null,selectedTile=null;
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
function presenterSource(person){const index=COMMANDERS.find(c=>c.name===person.name)?.portrait||person.portrait||1;return new URL(`public/weather-presenters/presenter-${String(index).padStart(2,'0')}.webp`,document.baseURI).href}
function applyPresenter(node,person){node.textContent='';node.classList.add('pixel-presenter');node.style.backgroundImage=`url("${presenterSource(person)}")`;node.setAttribute('role','img');node.setAttribute('aria-label',`${person.name}, ${person.role}`)}
function fresh(commander){const terrains=Object.keys(TERRAIN);return{turn:1,maxTurns:10,phase:'claim',claimedThisTurn:false,playerMoney:200,enemyMoney:200,commander,rival:COMMANDERS.filter(c=>c.name!==commander.name)[Math.floor(Math.random()*9)],powerUsed:false,boost:null,enemyBlocked:false,tiles:Array.from({length:16},(_,id)=>({id,terrain:terrains[Math.floor(Math.random()*4)],owner:null,building:null,effects:[]})),hand:drawHand(),message:'Welcome to the live map. Start by clicking one pulsing OPEN region.'}}
function drawHand(){return [...POWERS].sort(()=>Math.random()-.5).slice(0,3).map(p=>p.id)}function save(){localStorage.setItem(SAVE,JSON.stringify(state))}function load(){try{const s=JSON.parse(localStorage.getItem(SAVE));return s?.tiles?.length===16?s:null}catch{return null}}
function adjacent(id){const r=Math.floor(id/4),c=id%4;return state.tiles.filter(t=>{const tr=Math.floor(t.id/4),tc=t.id%4;return Math.abs(tr-r)+Math.abs(tc-c)===1})}function adjacency(tile){return 1+Math.min(.4,adjacent(tile.id).filter(t=>t.terrain===tile.terrain).length*.1)}
function production(tile,owner=tile.owner){if(!tile.building)return 0;let out=BUILDINGS[tile.building.type].production*MOD[tile.terrain][tile.building.type]*adjacency(tile);tile.effects.forEach(e=>out*=e.mult);if(owner===OWNER.PLAYER&&state.boost==='boost')out*=2;if(owner===OWNER.PLAYER&&state.boost==='farm'&&tile.building.type==='farm')out*=3;if(owner===OWNER.PLAYER&&state.boost==='solar'&&tile.building.type==='solar')out*=3;if(owner===OWNER.ENEMY&&state.boost==='eclipse')out*=.5;return Math.round(out)}
function phaseCopy(){return{
  claim:['Segment 1 · Claim a region','Click one highlighted OPEN region.','Continue to building →','1','Claim one open region','Click any pulsing tile marked OPEN. You may claim one region each turn.','Look for matching terrain beside each other.'],
  build:['Segment 2 · Build your economy','Choose a building card, then click an empty blue region.','Continue to forecast →','2','Choose a building, then a blue region','Click a building card below. Then place it on one of your empty blue tiles.','Farm likes grass · Mine likes mountain · Wind likes water · Solar likes desert.'],
  weather:['Segment 3 · Deliver the forecast','Choose a forecast card, then click a glowing valid target.','End turn →','3','Choose weather, then a glowing target','Helpful forecasts target your blue buildings. Severe weather targets red rival buildings.','You can skip this segment to save credits for the next turn.']
}[state.phase]}
function render(){const [title,help,next,number,coachTitle,coachText,coachTip]=phaseCopy();$('#phaseTitle').textContent=title;$('#phaseHelp').textContent=help;$('#phaseTop').textContent=`Segment ${number} of 3`;$('#coachNumber').textContent=number;$('#coachTitle').textContent=coachTitle;$('#coachText').textContent=coachText;$('#coachTip').querySelector('span').textContent=coachTip;$('#nextBtn').textContent=next;$('#turn').textContent=`${state.turn} / ${state.maxTurns}`;$('#playerMoney').textContent=state.playerMoney;$('#enemyMoney').textContent=state.enemyMoney;$('#playerName').textContent=state.commander.name;$('#enemyName').textContent=state.rival.name;$('#playerRole').textContent=state.commander.role;$('#enemyRole').textContent=state.rival.role;applyPresenter($('#playerAvatar'),state.commander);applyPresenter($('#enemyAvatar'),state.rival);$('#powerName').textContent=state.commander.power;$('#powerDesc').textContent=state.commander.desc;$('#powerBtn').disabled=state.powerUsed;$('#powerBtn').textContent=state.powerUsed?'Forecast already used':'Go live with forecast';$('#message').textContent=state.message;$('#broadcastTicker').textContent=`${state.commander.station} with ${state.commander.name} · ${title}`;$$('#phaseStepper [data-phase]').forEach((step,index)=>{const order=['claim','build','weather'];step.classList.toggle('active',step.dataset.phase===state.phase);step.classList.toggle('done',order.indexOf(step.dataset.phase)<order.indexOf(state.phase))});renderBoard();renderCards();if(selectedTile!=null)inspect(state.tiles[selectedTile]);save()}
function renderBoard(){const board=$('#board');board.innerHTML='';state.tiles.forEach(t=>{const b=t.building&&BUILDINGS[t.building.type],valid=isValidTarget(t),btn=document.createElement('button');btn.className=`tile ${t.terrain} ${t.owner||''} ${valid?'target':''} ${selectedTile===t.id?'selected':''}`;btn.dataset.id=t.id;btn.setAttribute('aria-label',`${TERRAIN[t.terrain].label}, ${t.owner||'unclaimed'}${b?', '+b.label:''}`);btn.innerHTML=`<div class="tile-top"><span>${TERRAIN[t.terrain].icon} ${TERRAIN[t.terrain].label}</span><i class="tile-owner"></i></div><div class="tile-center"><span class="tile-icon">${b?b.icon:TERRAIN[t.terrain].icon}</span><span class="tile-name">${b?b.label:'Unclaimed'}</span></div><div class="tile-bottom"><span>${t.effects.map(e=>e.icon).join(' ')||'No effects'}</span><b class="tile-prod">${b?'+'+production(t):'OPEN'}</b></div>${b?`<div class="hp"><i style="width:${Math.max(0,t.building.hp/b.durability*100)}%"></i></div>`:''}`;btn.onclick=()=>tileClick(t);board.append(btn)})}
function isValidTarget(t){if(state.phase==='claim')return !state.claimedThisTurn&&!t.owner;if(state.phase==='build')return selectedAction&&t.owner===OWNER.PLAYER&&!t.building;if(state.phase==='weather'&&selectedAction){const p=POWERS.find(x=>x.id===selectedAction);return !!t.building&&(p.benefit?t.owner===OWNER.PLAYER:t.owner===OWNER.ENEMY)}return false}
function renderCards(){const root=$('#cards');root.innerHTML='';let list=[];if(state.phase==='build')list=Object.entries(BUILDINGS).map(([id,x])=>({id,...x}));if(state.phase==='weather')list=state.hand.map(id=>POWERS.find(p=>p.id===id));$('#dockTitle').textContent=state.phase==='claim'?'Regional map':state.phase==='build'?'Available buildings':'Forecast cards';$('#dockHint').textContent=state.phase==='claim'?'Choose one pulsing OPEN region':state.phase==='build'?'First choose a card, then a blue region':'First choose weather, then a glowing target';if(!list.length){root.innerHTML='<p style="color:var(--muted);margin:8px">No card needed yet—click one of the pulsing OPEN regions above.</p>';return}list.forEach(a=>{const btn=document.createElement('button'),unaffordable=a.cost>state.playerMoney;btn.className=`action-card ${selectedAction===a.id?'selected':''}`;btn.disabled=unaffordable;btn.innerHTML=`<span class="emoji">${a.icon}</span><span class="cost">${a.cost} cr</span><strong>${a.label||a.name}</strong><small>${a.production?`Earns ${a.production} before terrain bonuses`:a.benefit?'Helpful · target your blue tile':'Severe · target a red rival'}</small>`;btn.onclick=()=>{selectedAction=selectedAction===a.id?null:a.id;state.message=selectedAction?`${a.label||a.name} selected. Now click a glowing region.`:'Card deselected.';render()};root.append(btn)})}
function tileClick(t){selectedTile=t.id;inspect(t);if(!isValidTarget(t)){state.message=state.phase==='claim'?'Choose a pulsing OPEN region.':selectedAction?'That region is not a valid target for this card.':'Choose a card first, then click a glowing region.';render();return}if(state.phase==='claim'){t.owner=OWNER.PLAYER;state.claimedThisTurn=true;state.message=`${TERRAIN[t.terrain].label} is now yours. Great—continue to the building segment.`;render();return}if(state.phase==='build'){const b=BUILDINGS[selectedAction];t.building={type:selectedAction,hp:b.durability};state.playerMoney-=b.cost;state.message=`${b.label} built on ${TERRAIN[t.terrain].label}. It will earn ${production(t)} credits at the end of this turn.`;selectedAction=null;render();return}const p=POWERS.find(x=>x.id===selectedAction);t.effects.push({id:p.id,icon:p.icon,mult:p.mult,turns:p.duration});if(p.damage){t.building.hp-=Math.round(p.damage*BUILDINGS[t.building.type].sensitivity);if(t.building.hp<=0){t.building=null;t.effects=[]}}state.playerMoney-=p.cost;state.message=`${p.name} is live on the map. You may use another card or end the turn.`;state.hand=state.hand.filter(id=>id!==p.id);selectedAction=null;render()}
function inspect(t){const b=t.building&&BUILDINGS[t.building.type],desc=`${TERRAIN[t.terrain].label} region${b?` with a ${b.label}`:' with no building yet'}. ${adjacency(t)>1?'Matching neighboring terrain is boosting production.':'Claim matching terrain beside it to earn an adjacency bonus.'}`;$('#inspectTitle').textContent=b?b.label:TERRAIN[t.terrain].label;$('#inspectDesc').textContent=desc;$('#inspectStats').innerHTML=`<div class="stat-row"><span>Weather desk</span><b>${t.owner==='player'?'Yours':t.owner==='enemy'?'Rival':'Open region'}</b></div><div class="stat-row"><span>Credits each turn</span><b>${b?'+'+production(t):'—'}</b></div><div class="stat-row"><span>Terrain match</span><b>${b?MOD[t.terrain][t.building.type].toFixed(1)+'×':'—'}</b></div><div class="stat-row"><span>Neighbor bonus</span><b>${adjacency(t).toFixed(1)}×</b></div>`;$('#sheetTitle').textContent=$('#inspectTitle').textContent;$('#sheetDesc').textContent=desc;if(innerWidth<761)$('#sheet').classList.add('show')}
function nextPhase(){if(state.phase==='claim'&&!state.tiles.some(t=>t.owner===OWNER.PLAYER)){state.message='Claim a territory before continuing.';render();return}if(state.phase==='claim')state.phase='build';else if(state.phase==='build')state.phase='weather';else endTurn();selectedAction=null;selectedTile=null;render()}
function enemyTurn(){const open=state.tiles.filter(t=>!t.owner);if(open.length){const t=open[Math.floor(Math.random()*open.length)];t.owner=OWNER.ENEMY;const affordable=Object.entries(BUILDINGS).filter(([,b])=>b.cost<=state.enemyMoney).sort((a,b)=>b[1].production-a[1].production);if(affordable.length){const [type,b]=affordable[0];t.building={type,hp:b.durability};state.enemyMoney-=b.cost}}if(!state.enemyBlocked){const targets=state.tiles.filter(t=>t.owner===OWNER.PLAYER&&t.building);if(targets.length&&state.enemyMoney>=25){const p=POWERS.filter(p=>!p.benefit&&p.cost<=state.enemyMoney)[Math.floor(Math.random()*6)],t=targets[Math.floor(Math.random()*targets.length)];if(p){t.effects.push({id:p.id,icon:p.icon,mult:p.mult,turns:p.duration});t.building.hp-=p.damage||0;state.enemyMoney-=p.cost;if(t.building.hp<=0){t.building=null;t.effects=[]}}}}state.enemyBlocked=false}
function income(owner){return state.tiles.filter(t=>t.owner===owner).reduce((n,t)=>n+production(t,owner),0)}function maintenance(owner){return state.tiles.filter(t=>t.owner===owner&&t.building).reduce((n,t)=>n+BUILDINGS[t.building.type].maintenance,0)}
function endTurn(){const pi=income(OWNER.PLAYER),ei=income(OWNER.ENEMY);state.playerMoney+=pi-maintenance(OWNER.PLAYER);state.enemyMoney+=ei-maintenance(OWNER.ENEMY);state.tiles.forEach(t=>t.effects=t.effects.map(e=>({...e,turns:e.turns-1})).filter(e=>e.turns>0));enemyTurn();state.boost=null;if(state.turn>=state.maxTurns){showResult();return}state.turn++;state.phase='claim';state.claimedThisTurn=false;state.hand=drawHand();state.message=`Turn ${state.turn} is live. Your buildings earned ${pi} credits last turn; the rival earned ${ei}. Start by claiming one open region.`;selectedAction=null;selectedTile=null;render()}
function useCommander(){if(state.powerUsed)return;state.powerUsed=true;const k=state.commander.kind;if(['boost','farm','solar','eclipse'].includes(k))state.boost=k;if(k==='money')state.playerMoney+=60;if(k==='freeze')state.tiles.filter(t=>t.owner===OWNER.ENEMY&&t.building).forEach(t=>t.effects.push({id:'freeze',icon:'SNOW',mult:.25,turns:1}));if(k==='damage')state.tiles.filter(t=>t.owner===OWNER.ENEMY&&t.building).forEach(t=>{t.building.hp-=18;if(t.building.hp<=0){t.building=null;t.effects=[]}});if(k==='remove'){const ts=state.tiles.filter(t=>t.owner===OWNER.ENEMY&&t.building);if(ts.length)ts[Math.floor(Math.random()*ts.length)].building=null}if(k==='block')state.enemyBlocked=true;if(k==='clear')state.tiles.filter(t=>t.owner===OWNER.PLAYER).forEach(t=>t.effects=t.effects.filter(e=>e.mult>=1));state.message=`${state.commander.power} deployed.`;render()}
function showResult(){localStorage.removeItem(SAVE);const win=state.playerMoney>=state.enemyMoney;$('#resultTitle').textContent=win?'Forecast victory':'Rival desk wins';$('#resultText').textContent=win?'Your meteorologist delivered the stronger ten-turn forecast and finished with more credits.':'The rival weather desk finished with more credits. Rebuild the region and try a different forecast.';$('#resultScore').textContent=`${state.playerMoney} — ${state.enemyMoney}`;$('#resultOverlay').classList.remove('hidden')}
function openTutorial(){localStorage.setItem(TUTORIAL,'1');$('#tutorialOverlay').classList.remove('hidden')}
function closeTutorial(){$('#tutorialOverlay').classList.add('hidden')}
function showCommanders(){const root=$('#characterGrid');root.innerHTML='';COMMANDERS.forEach(c=>{const b=document.createElement('button');b.className='character-card';b.innerHTML=`<div class="character-portrait pixel-presenter" role="img" aria-label="${c.name}, ${c.role}" style="background-image:url('${presenterSource(c)}')"><span class="character-live">LIVE</span></div><small>${c.role}</small><strong>${c.name}</strong><span>${c.station} · ${c.city}</span><em>Signature: ${c.power}</em>`;b.onclick=()=>{$$('.character-card').forEach(x=>x.classList.remove('selected'));b.classList.add('selected');$('#startBtn').disabled=false;$('#startBtn').onclick=()=>{state=fresh(c);$('#commanderOverlay').classList.add('hidden');render();if(!localStorage.getItem(TUTORIAL))openTutorial()}};root.append(b)})}
$('#nextBtn').onclick=nextPhase;$('#powerBtn').onclick=useCommander;$('#helpBtn').onclick=openTutorial;$('#tutorialClose').onclick=closeTutorial;$('#tutorialStart').onclick=closeTutorial;$('#newBtn').onclick=()=>{localStorage.removeItem(SAVE);location.reload()};$('#replayBtn').onclick=()=>location.reload();$('#closeSheet').onclick=()=>$('#sheet').classList.remove('show');$('#soundBtn').onclick=e=>e.currentTarget.textContent=e.currentTarget.textContent==='Sound off'?'Sound on':'Sound off';const prior=load();if(prior){state=prior;$('#commanderOverlay').classList.add('hidden');render()}else showCommanders();
